#!/usr/bin/env node
/*
 * Generates the files the HTML prototype needs to run from file:// (no fetch):
 *   design/prototypes/flujo/capture.flow.js   window.CAPTURE_FLOW + window.CAPTURE_TEMPLATE
 *   design/prototypes/flujo/nomina.sample.js  window.NOMINA_SAMPLE (real roster subset)
 *   design/prototypes/flujo/flow-machine.js   copy of contracts/flows/flow-machine.js
 *
 * Sources: contracts/flows/capture.flow.json, contracts/templates/<id>.json and
 * data/establecimientos/nomina-2025.json. Never edit the generated files by hand.
 *
 * Usage: node contracts/flows/export-prototype.js [--template generales-2023]
 */
'use strict';
const fs = require('fs');
const path = require('path');

const REPO = path.resolve(__dirname, '..', '..');
const OUT = path.join(REPO, 'design', 'prototypes', 'flujo');
const argv = process.argv.slice(2);
const templateId = argv.includes('--template') ? argv[argv.indexOf('--template') + 1] : 'generales-2023';

// Roster subset shown by the cascading pickers: every district and section name,
// but polling places only for these sections (keeps the file small).
const INCLUDED_SECTIONS = [
  { distrito: '01', seccion: '001' }, // CABA · Comuna 1
  { distrito: '02', seccion: '004' }  // Buenos Aires · Avellaneda
];

function readJson(relative) {
  return JSON.parse(fs.readFileSync(path.join(REPO, relative), 'utf8'));
}
function banner(sources) {
  return '/* GENERATED by contracts/flows/export-prototype.js from ' + sources.join(', ') +
    '. Do not edit: regenerate with `node contracts/flows/export-prototype.js`. */\n';
}

const flow = readJson('contracts/flows/capture.flow.json');
const template = readJson(path.join('contracts', 'templates', templateId + '.json'));
const roster = readJson('data/establecimientos/nomina-2025.json');

const subset = {
  source: roster.source,
  note: roster.note + ' Subconjunto para el prototipo: nombres de todos los distritos y secciones; establecimientos sólo en ' +
    INCLUDED_SECTIONS.map((s) => s.distrito + '/' + s.seccion).join(' y ') + '.',
  included: INCLUDED_SECTIONS.map((s) => s.distrito + '/' + s.seccion),
  distritos: roster.distritos.map((d) => ({
    id: d.id,
    nombre: d.nombre,
    secciones: d.secciones.map((s) => {
      const included = INCLUDED_SECTIONS.some((x) => x.distrito === d.id && x.seccion === s.id);
      return { id: s.id, nombre: s.nombre, locales: included ? s.locales : null };
    })
  }))
};

fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(path.join(OUT, 'capture.flow.js'),
  banner(['contracts/flows/capture.flow.json', 'contracts/templates/' + templateId + '.json']) +
  'window.CAPTURE_FLOW = ' + JSON.stringify(flow, null, 1) + ';\n' +
  'window.CAPTURE_TEMPLATE = ' + JSON.stringify(template, null, 1) + ';\n');
fs.writeFileSync(path.join(OUT, 'nomina.sample.js'),
  banner(['data/establecimientos/nomina-2025.json']) +
  'window.NOMINA_SAMPLE = ' + JSON.stringify(subset) + ';\n');
fs.writeFileSync(path.join(OUT, 'flow-machine.js'),
  banner(['contracts/flows/flow-machine.js']) + fs.readFileSync(path.join(__dirname, 'flow-machine.js'), 'utf8'));

const locales = subset.distritos.reduce((n, d) => n + d.secciones.reduce((m, s) => m + (s.locales ? s.locales.length : 0), 0), 0);
console.log('wrote ' + OUT + ' (template ' + templateId + ', ' + locales + ' polling places in the roster subset)');
